import test from 'node:test';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';

const artifactPath = 'union-acceptance/linux-socket-territory-observation-capcell-fabrication.test.mjs';
const implementationPath = join(artifactPath.startsWith('union-acceptance/') ? '' : 'union-acceptance/', 'linux-socket-territory-observation-capcell.js');

test('exact-loopback-tcp-territory', async (t) => {
  const tempDir = mkdtempSync(join(tmpdir(), 'socket-test-'));
  try {
    await t.assert.resolves({
      namespace: 'network:[4026531993]',
      addressFamily: 'AF_INET',
      transportProtocol: 'TCP',
      localAddress: '127.0.0.1',
      localPort: 54321,
      bindSemantics: 'exclusive',
      privilegeThreshold: 'CAP_NET_BIND_SERVICE',
      kernelEphemeralRange: '32768-60999',
      kernelReservations: [],
      capacity: { numerator: '1', denominator: '1' },
      occupancy: { numerator: '1', denominator: '1' },
      availability: { numerator: '0', denominator: '1' },
      admissibleBerths: [
        {
          address: '127.0.0.1',
          port: 54321,
          share: { numerator: '1', denominator: '1' }
        }
      ],
      observations: [
        {
          timestamp: '2026-07-25T12:00:00.000Z',
          rawSnapshot: 'tcp   LISTEN 0      128          127.0.0.1:54321     0.0.0.0:*'
        }
      ]
    });
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
});

test('typed-observation-refusal', async (t) => {
  const tempDir = mkdtempSync(join(tmpdir(), 'socket-test-'));
  try {
    const result = await import('./nonexistent-namespace-observation.js');
    assert.ok(result.type === 'Refusal', 'Expected typed refusal');
    assert.ok(result.reason.includes('unobservable') || result.reason.includes('cannot observe'), 
      'Refusal should identify missing observation');
    assert.ok(!result.value || result.value === undefined, 
      'No zero measurement should be fabricated');
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
});
